using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "MoonieCharacterAchievement", menuName = "Data/Characters/MoonieCharacterAchievement")]
public class MoonieCharacterAchievement : CharacterAchievement
{
	[SerializeField]
	private PlagueDoctorAchievementData plagueDoctorAchievementData;

	[SerializeField]
	private SadisticPlanAchievementData sadisticPlanAchievementData;

	public override void OnEnemyPurified(int purifyAmount, CorruptedAnimalCorruptionStats corruptedAnimalCorruptionStats, GameObject source)
	{
		sadisticPlanAchievementData.SadisticPlanUnlock(corruptedAnimalCorruptionStats, source);
	}

	public override void OnStartEndOfBattleState()
	{
		plagueDoctorAchievementData.Unlock();
	}
}
